//! Actual metadata-only native control. Root runs this once under its booked QA
//! envelope after normal sealing; this source author executed no control.
use crate::{io::{self,Bound,Deadline},package::{self,Publisher},lifecycle};
use anyhow::{Context,Result,ensure};use serde::Deserialize;use serde_json::{Value,json};use std::{fs,path::{Path,PathBuf},os::unix::fs::PermissionsExt,time::Duration};
#[derive(Deserialize)]#[serde(deny_unknown_fields)]pub struct Config{schema:String,generation:String,sealer:Bound,state:PathBuf}
fn generation(s:&str)->Result<()>{ensure!(!s.is_empty()&&s.len()<=40&&s.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'-'),"unique native-control generation");Ok(())}
fn source(argv:&[String])->Result<String>{ensure!(argv.len()==3&&argv[1]=="--metadata-control-exec"&&argv.iter().all(|s|!s.contains(char::is_whitespace)&&!s.contains(['\n','\r','%','"','\\'])),"exact harmless control argv");Ok(format!("[Unit]\nDescription=Metadata-only finite original lifecycle control\n[Service]\nType=exec\nUser=root\nGroup=root\nRestart=no\nRemainAfterExit=no\nMemoryAccounting=yes\nMemoryMax=64M\nMemorySwapMax=0\nCPUQuota=100%\nTasksMax=16\nRuntimeMaxSec=10s\nTimeoutStopSec=2s\nKillMode=control-group\nUMask=0077\nNoNewPrivileges=yes\nPrivateNetwork=yes\nProtectSystem=strict\nProtectHome=read-only\nCapabilityBoundingSet=\nAmbientCapabilities=\nStandardOutput=journal\nStandardError=journal\nExecStart={}\n",argv.join(" ")))}
fn install(p:&mut Publisher<'_>,label:&str,unit:&str,argv:&[String],d:&Deadline)->Result<String>{lifecycle::absent(unit,d)?;let keeper=unit.trim_end_matches(".service").to_owned()+"-retain.target";lifecycle::absent(&keeper,d)?;let members=p.save(label,vec![(unit.into(),source(argv)?.into_bytes()),(keeper.clone(),lifecycle::keeper_source(unit).into_bytes())],d)?;package::install(unit,&io::as_bound(&members[unit])?)?;package::install(&keeper,&io::as_bound(&members[&keeper])?)?;lifecycle::ctl(&["daemon-reload"],d)?;Ok(keeper)}
fn payload(unit:&str,iid:&str,image:&Path,token:&str,d:&Deadline)->Result<Value>{let raw=io::query(vec!["/usr/bin/journalctl".into(),"--all".into(),"--no-pager".into(),"--output=json".into(),"--lines=32".into(),format!("_SYSTEMD_UNIT={unit}"),format!("_SYSTEMD_INVOCATION_ID={iid}")],d)?;let mut matches=Vec::new();for row in raw.split(|b|*b==b'\n').filter(|r|!r.is_empty()){let row:Value=serde_json::from_slice(row)?;if row["_UID"]=="0"&&row["_EXE"]==image.to_string_lossy().as_ref()&&row["_SYSTEMD_UNIT"]==unit&&row["_SYSTEMD_INVOCATION_ID"]==iid && let Some(message)=row["MESSAGE"].as_str() && let Ok(v)=serde_json::from_str::<Value>(message) && v["schema"]=="first128-driver-harmless-native-control-exec-v1"&&v["token"]==token&&v["input_body_reads"]==0&&v["campaign_mutations"]==false{matches.push(row);}}ensure!(matches.len()==1,"unique actual original harmless control payload");Ok(matches.remove(0))}
pub fn exec(token:&str)->Result<()>{generation(token)?;ensure!(unsafe{libc::geteuid()}==0,"control child root");let iid=std::env::var("INVOCATION_ID")?;ensure!(io::hex(&iid,32),"actual control child native identity");println!("{}",json!({"schema":"first128-driver-harmless-native-control-exec-v1","token":token,"invocation_id":iid,"input_body_reads":0,"campaign_mutations":false,"replay_launch_authorized":false}));std::thread::sleep(Duration::from_millis(400));Ok(())}
pub fn run(config:&Bound,self_image:&Bound)->Result<()> {
 package::normal(self_image,"0555",32<<20)?;package::normal(config,"0444",1<<20)?;let c:Config=serde_json::from_value(io::json_bound(config)?)?;ensure!(unsafe{libc::geteuid()}==0&&c.schema=="first128-driver-original-native-metadata-control-config-v1","metadata control/root scope");generation(&c.generation)?;package::normal(&c.sealer,"0555",32<<20)?;io::scope(&c.state)?;ensure!(c.state.starts_with("/home/sol/.jetstreamer-private")&&!c.state.exists(),"fresh private metadata control state");fs::create_dir(&c.state)?;fs::set_permissions(&c.state,fs::Permissions::from_mode(0o700))?;let d=Deadline::new(90);let mut p=Publisher{stage:c.state.clone(),prefix:format!("horizon-first128-driver-qa-{}",c.generation),sealer:&c.sealer,count:0};
 let once=format!("horizon-first128-driver-control-{}-once.service",c.generation);let tick=format!("horizon-first128-driver-control-{}-tick.service",c.generation);let timer=tick.trim_end_matches(".service").to_owned()+".timer";let argv=vec![self_image.path.display().to_string(),"--metadata-control-exec".into(),c.generation.clone()];
 let once_keeper=install(&mut p,"once-service",&once,&argv,&d)?;let original=lifecycle::original(&mut p,"once-native",&once,&once_keeper,&argv,&d)?;let once_payload=payload(&once,original["invocation_id"].as_str().context("once IID")?,&self_image.path,&c.generation,&d)?;let original_bound=p.document("once-original","original.json",&json!({"schema":"first128-driver-actual-keeper-original-control-v1","original":original,"actual_original_payload":once_payload,"campaign_authority":false}),&d)?;
 let tick_keeper=install(&mut p,"tick-service",&tick,&argv,&d)?;let tick_first=lifecycle::original(&mut p,"tick-prior-native",&tick,&tick_keeper,&argv,&d)?;let prior_iid=tick_first["invocation_id"].clone();p.document("tick-prior-original","original.json",&tick_first,&d)?;
 lifecycle::absent(&timer,&d)?;let timer_source=format!("[Unit]\nDescription=One real metadata-only lifecycle timer fire\n[Timer]\nOnActiveSec=1s\nOnUnitInactiveSec=30s\nAccuracySec=1ms\nUnit={tick}\n");let timer_members=p.save("tick-timer",vec![(timer.clone(),timer_source.into_bytes())],&d)?;package::install(&timer,&io::as_bound(&timer_members[&timer])?)?;lifecycle::ctl(&["daemon-reload"],&d)?;
 let event=lifecycle::arm_and_wait_timer_for(&mut p,&tick,&timer,"ACTUAL_METADATA_TIMER_FIRE.json",&d)?;let after=io::native(&tick,&d)?;io::terminal(&after,&tick)?;io::unit_command(&after,&argv)?;ensure!(after["InvocationID"]!=prior_iid&&after["InvocationID"]==event["event"]["INVOCATION_ID"],"timer must create distinct actual control invocation");let timer_payload=payload(&tick,after["InvocationID"].as_str().context("actual timer IID")?,&self_image.path,&c.generation,&d)?;
 // Stop only this exact one-shot QA timer after its genuine first completion.
 // Production timers, parent, guards, original keepers and receipts stay intact.
 let before_stop=io::native(&timer,&d)?;lifecycle::ctl(&["stop",&timer],&d)?;let stopped=io::native(&timer,&d)?;ensure!(stopped["ActiveState"]=="inactive"&&stopped["SubState"]=="dead","exact QA timer terminal");
 let receipt=json!({"schema":"first128-driver-actual-original-keeper-and-timer-kernel-control-v1","program":self_image,"configuration":config,"original_once_completion":original_bound,"actual_timer_fire":event,"actual_timer_payload":timer_payload,"actual_timer_before_stop":before_stop,"actual_exact_QA_timer_stopped":stopped,"original_tick_terminal":after,"shared_production_original_and_timer_primitives_exercised":true,"actual_metadata_only":true,"input_body_reads":0,"resource_observations":0,"replay_launch_authorized":false,"publication_authorized":false,"r2_mutations":false});let receipt_bound=p.document("kernel-control-completion","completion.json",&receipt,&d)?;println!("{}",json!({"actual_native_metadata_control":receipt_bound,"original_once_IID":original["invocation_id"],"actual_timer_IID":after["InvocationID"],"campaign_authority":false}));Ok(())
}
#[cfg(test)]mod tests{use super::*;#[test]fn harmless_control_cannot_select_campaign_routes_or_inject_native_source(){let good=vec!["/usr/local/lib/jetstreamer/qa/driver".into(),"--metadata-control-exec".into(),"control-v2".into()];let s=source(&good).unwrap();assert!(s.contains("PrivateNetwork=yes\n")&&!s.contains("EnvironmentFile="));let mut bad=good.clone();bad[1]="release-first163128".into();assert!(source(&bad).is_err());let mut bad=good;bad[2]="bad\nExecStart=/bad".into();assert!(source(&bad).is_err());assert!(generation("../campaign").is_err());}}
